func SortClonesBySize(dups [][]*syntax.Node) [][]*syntax.Node {
	sortables := make([]Sortable, len(dups))
	for i, nodes := range dups {
		sortables[i] = NodeGroupSortable{Nodes: nodes}
	}
	SortByCriteria(sortables, SortBySize)

	// Convert back to [][]*syntax.Node array
	result := make([][]*syntax.Node, len(dups))
	for i, sortable := range sortables {
		result[i] = sortable.(NodeGroupSortable).Nodes
	}
	return result
}

